<?php
declare(strict_types=1);
require __DIR__.'/mailbox-recovery-support.php';
function mailboxRace(MailboxEnvironment $m,string $action,string $mode,string $code='owned-approval'):array {
    $d=null;if($action==='confirm'){foreach(array_reverse($m->ids()) as $id){$n=$m->service->notification($id);if($n!==null&&$n->notice()->type()==='recover_address'){$d=$n;break;}}if($d===null){$d=$GLOBALS['lastMailboxRaceDelivery'];}else{$GLOBALS['lastMailboxRaceDelivery']=$d;}}
    $config=['mysql'=>$m->e->mysql,'socket'=>getenv('SOSECURITY_TEST_MYSQL_SOCKET'),'directory'=>$m->e->directory,'database'=>$m->e->directory.'/registration.sqlite','time'=>$m->e->clock->time,'selector'=>$d===null?'':$d->selector(),'token'=>$d===null?'':$d->notice()->token(),'approval_code'=>$code,'pause'=>in_array($mode,['before','after'],true)?$mode:'','ready'=>$m->e->directory.'/ready'];$path=$m->e->directory.'/race.json';file_put_contents($path,json_encode($config));chmod($path,0600);
    $command='python3 '.escapeshellarg(__DIR__.'/mailbox_recovery_race.py').' '.escapeshellarg(PHP_BINARY).' '.escapeshellarg($path).' '.escapeshellarg($action).' '.escapeshellarg($mode);$process=proc_open($command,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);fclose($pipes[0]);$output=stream_get_contents($pipes[1]);$errors=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$status=proc_close($process);unlink($path);if(file_exists($config['ready'])){unlink($config['ready']);}if($status!==0){throw new RuntimeException('Owned mailbox race failed: '.$output.$errors);}return json_decode($output,true);
}
mailboxCase(static function(MailboxEnvironment $m):void{$before=$m->e->account();$r=mailboxRace($m,'request','parallel');Check::same(24,$r['workers']);Check::same(24,$r['successful']);Check::same(2,count($m->ids()));Check::same($before,$m->e->account());});
mailboxCase(static function(MailboxEnvironment $m):void{$d=$m->begin();$before=$m->e->account();$r=mailboxRace($m,'confirm','parallel');Check::same(24,$r['workers']);Check::same(1,$r['successful']);Check::same('rescued@example.com',$m->e->account()['address']);Check::same($before['password'],$m->e->account()['password']);Check::same(4,count($m->ids()));Check::same(false,$m->confirm($d));});
foreach(['before','after'] as $mode){mailboxCase(static function(MailboxEnvironment $m)use($mode):void{$d=$m->begin();$before=$m->e->account();$r=mailboxRace($m,'confirm',$mode,'original');Check::same(true,$r['killed']);if($mode==='before'){Check::same($before,$m->e->account());Check::same(2,count($m->ids()));$retry=mailboxRace($m,'confirm','once','original');Check::same(0,$retry['successful']);Check::same($before,$m->e->account());$fresh=mailboxRace($m,'confirm','once','new-explicit-approval');Check::same(1,$fresh['successful']);Check::same('rescued@example.com',$m->e->account()['address']);Check::same(4,count($m->ids()));}else{Check::same('rescued@example.com',$m->e->account()['address']);Check::same($before['password'],$m->e->account()['password']);Check::same(4,count($m->ids()));$retry=mailboxRace($m,'confirm','once','original');Check::same(0,$retry['successful']);Check::same(4,count($m->ids()));}});}
echo 'PASS mailbox actual concurrency: '.Check::$assertions.' assertions '.(($argv[1]??'')==='mysql'?'MySQL':'SQLite').' PHP '.PHP_VERSION."; 48 real workers, two SIGKILL, consumed test approval not refunded, no network or production state\n";
